            )
            return 0
        if not _attempt(
            store, args.tenant_id, None,
            audit_mod.ACTION_IMPORT, audit_mod.OUTCOME_REJECTED,
        ):
            return 1
        if result.status == restore_mod.RESTORE_SAME_TENANT_CONFLICT:
