import os, uuid

class FakeHSM:
    provider_id = "fake-hsm"
    capabilities = {
        "algorithms": ["AES256", "RSA2048"],
        "operations": ["generate", "rotate", "import_material",
                       "export_material", "delete"],
    }
    def __init__(self):
        self.store = {}
        self.configured = None
    def configure(self, data_dir):
        self.configured = data_dir
    def generate(self, algorithm):
        # delegate to local crypto via import to keep test simple
        from cryptography.hazmat.primitives.asymmetric import rsa
        from cryptography.hazmat.primitives import serialization
        import base64
        h = "hsm-" + uuid.uuid4().hex
        if algorithm == "AES256":
            raw = base64.b64encode(os.urandom(32)).decode()
            self.store[h] = (None, raw); return {"handle": h, "public_key": None, "encrypted_material": "hsmblob:"+raw}
        k = rsa.generate_private_key(public_exponent=65537, key_size=2048)
        pem = k.private_bytes(serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()).decode()
        pub = k.public_key().public_bytes(serialization.Encoding.PEM, serialization.PublicFormat.SubjectPublicKeyInfo).decode()
        self.store[h] = (pub, pem)
        return {"handle": h, "public_key": pub, "encrypted_material": "hsmblob:"+pem}
