import json
import os
import shutil
import socket
import subprocess
import sys
import time
import urllib.request
import urllib.error

ROOT = "/var/tmp/solo-b/task01/task009"


def free_port():
    s = socket.socket()
    s.bind(("127.0.0.1", 0))
    p = s.getsockname()[1]
    s.close()
    return p


class Server:
    def __init__(self, data_dir, port=None, env_extra=None):
        self.data_dir = data_dir
        self.port = port if port is not None else free_port()
        env = dict(os.environ)
        if env_extra:
            env.update(env_extra)
        self.proc = subprocess.Popen(
            [sys.executable, "-m", "keymgr", "--data-dir", data_dir,
             "serve", "--host", "127.0.0.1", "--port", str(self.port)],
            cwd=ROOT, env=env,
            stdout=subprocess.DEVNULL, stderr=subprocess.PIPE,
        )

    def __enter__(self):
        for n in range(40):
            if self.proc.poll() is not None:
                raise RuntimeError("exited: " + self.proc.stderr.read().decode())
            try:
                self.req("GET", "/v1/policy?tenant_id=__probe__", operator="x")
            except urllib.error.HTTPError:
                return self
            except Exception as e:
                print("n", n, type(e).__name__, e, flush=True)
                time.sleep(0.2)
        raise RuntimeError("deaf")

    def __exit__(self, *a):
        self.proc.terminate()
        self.proc.wait(timeout=5)

    def req(self, method, path, operator=None, body=None, tenant_header=None):
        url = "http://127.0.0.1:%d%s" % (self.port, path)
        data = json.dumps(body).encode() if body is not None else None
        r = urllib.request.Request(url, data=data, method=method)
        if data is not None:
            r.add_header("Content-Type", "application/json")
        if operator is not None:
            r.add_header("X-Operator-Id", operator)
        if tenant_header is not None:
            r.add_header("X-Tenant-Id", tenant_header)
        try:
            with urllib.request.urlopen(r, timeout=5) as resp:
                return resp.status, json.loads(resp.read().decode())
        except urllib.error.HTTPError as e:
            return e.code, json.loads(e.read().decode())


shutil.rmtree("/tmp/tX", ignore_errors=True)
os.makedirs("/tmp/tX")
with Server("/tmp/tX") as s:
    print("SUCCESS", s.port)

