import os, signal, socket, subprocess, sys, time, shutil
import urllib.request, urllib.error

ROOT = "/var/tmp/solo-b/task01/task009"


def cleanup_orphans():
    # Kill python procs whose cmdline is ['python','-m','keymgr',...,'serve'].
    # This cleaner's own cmdline is this file, so it never matches itself.
    import glob
    me = os.getpid()
    for raw in glob.glob("/proc/[0-9]*/cmdline"):
        try:
            pid = int(raw.split("/")[2])
        except (IndexError, ValueError):
            continue
        if pid == me:
            continue
        try:
            parts = open(raw, "rb").read().split(b"\0")
            args = [p.decode() for p in parts if p]
        except OSError:
            continue
        if len(args) >= 2 and "-m" in args and "keymgr" in args and "serve" in args:
            try:
                os.kill(pid, signal.SIGKILL)
            except OSError:
                pass


def launch(data_dir, port, env_extra=None):
    env = dict(os.environ)
    if env_extra:
        env.update(env_extra)
    return subprocess.Popen(
        [sys.executable, "-m", "keymgr", "--data-dir", data_dir,
         "serve", "--host", "127.0.0.1", "--port", str(port)],
        cwd=ROOT, env=env,
        stdout=subprocess.DEVNULL, stderr=subprocess.PIPE,
        stdin=subprocess.DEVNULL, start_new_session=True,
    )


def wait_up(proc, port, seconds=8):
    t0 = time.time()
    last = None
    while time.time() - t0 < seconds:
        if proc.poll() is not None:
            err = proc.stderr.read().decode()
            return "exited rc=%s err=%s" % (proc.returncode, err[:500])
        try:
            req = urllib.request.Request(
                "http://127.0.0.1:%d/v1/policy?tenant_id=x" % port,
                headers={"X-Operator-Id": "z"})
            urllib.request.urlopen(req, timeout=2)
        except urllib.error.HTTPError:
            return "UP %.2fs" % (time.time() - t0)
        except Exception as e:
            last = e
            time.sleep(0.15)
    return "DEAF last=%r" % last


def stop(proc):
    try:
        os.killpg(os.getpgid(proc.pid), signal.SIGKILL)
    except OSError:
        pass


cleanup_orphans()
shutil.rmtree("/tmp/tA", ignore_errors=True)
os.makedirs("/tmp/tA")
for port in (8601, 8602, 8603):
    p = launch("/tmp/tA", port)
    res = wait_up(p, port)
    print("port %s -> %s" % (port, res), flush=True)
    stop(p)
    p.wait()
print("done")

